import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.wVcpyw2-.js";const c=JSON.parse('{"title":"微信（小程序 / 公众号 / 支付）","description":"微信（小程序 / 公众号 / 支付）：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/wechat.md","filePath":"features/wechat.md","lastUpdated":1785051348000}'),n={name:"features/wechat.md"};function s(l,t,i,d,h,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="微信-小程序-公众号-支付" tabindex="-1">微信（小程序 / 公众号 / 支付） <a class="header-anchor" href="#微信-小程序-公众号-支付" aria-label="Permalink to &quot;微信（小程序 / 公众号 / 支付）&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>配置微信小程序、公众号与微信支付，使用户可通过微信登录、接收模板消息并完成在线支付。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>站点已完成初始化，<strong>系统设置 → 网站信息</strong> 中填写的域名与生产环境 HTTPS 地址一致。</li><li>已在微信公众平台注册小程序、公众号（如需 H5 微信登录）。</li><li>已在微信支付商户平台开通收单，并将小程序 AppID 与商户号绑定。</li><li>您的账号具备 <strong>系统配置</strong> 的修改权限（超级管理员，或在 <strong>系统设置 → 账号权限</strong> 中已分配相应权限）。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><h3 id="_1-微信小程序" tabindex="-1">1. 微信小程序 <a class="header-anchor" href="#_1-微信小程序" aria-label="Permalink to &quot;1. 微信小程序&quot;">​</a></h3><p>路径：<strong>系统设置 → 系统配置 → 微信小程序</strong> Tab</p><table tabindex="0"><thead><tr><th>配置项</th><th>填写来源</th></tr></thead><tbody><tr><td>AppID</td><td>微信公众平台 → 开发管理 → 开发设置</td></tr><tr><td>AppSecret</td><td>同上</td></tr><tr><td>原始 ID</td><td>部分能力需要时填写</td></tr></tbody></table><p>填写后点击 <strong>「立即获取 Token」</strong>，显示成功即表示与微信服务器连通。</p><h3 id="_2-微信公众号" tabindex="-1">2. 微信公众号 <a class="header-anchor" href="#_2-微信公众号" aria-label="Permalink to &quot;2. 微信公众号&quot;">​</a></h3><p>路径：<strong>系统设置 → 系统配置 → 微信公众号</strong> Tab</p><p>填写公众号 AppID、AppSecret 等参数。用于 H5 网页微信登录与公众号模板消息。</p><p>配置完成后同样可测试 Token。</p><h3 id="_3-微信支付" tabindex="-1">3. 微信支付 <a class="header-anchor" href="#_3-微信支付" aria-label="Permalink to &quot;3. 微信支付&quot;">​</a></h3><p>路径：<strong>系统设置 → 系统配置 → 微信支付</strong> Tab</p><p><strong>完整逐步配置</strong>（商户平台绑定 AppID、API 证书、回调 URL、后台逐字段、提现打款、验收 checklist）请参阅：</p><p>👉 <strong><a href="/features/wechat-pay">微信支付（完整配置手册）</a></strong></p><p>此处仅列回调地址：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://你的域名/api/payment/wx-notify</span></span></code></pre></div><p>请将 <code>你的域名</code> 替换为 <strong>网站信息</strong> 中的正式 HTTPS 域名。</p><h3 id="_4-开启用户微信登录" tabindex="-1">4. 开启用户微信登录 <a class="header-anchor" href="#_4-开启用户微信登录" aria-label="Permalink to &quot;4. 开启用户微信登录&quot;">​</a></h3><p>路径：<strong>区域管理 → 用户配置</strong></p><p>在目标区域（或「平台默认」）中开启：</p><ul><li><strong>允许微信小程序登录</strong></li><li><strong>允许微信公众号登录</strong>（如需 H5 登录）</li></ul><p>未开启时，即使用户端有微信入口，登录也会被拒绝。</p><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>微信登录按 <strong>区域</strong> 控制，不在系统配置 Tab 里单独开关。</p><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>区域管理 → 用户配置</strong></td><td>各区域是否允许小程序 / 公众号登录</td></tr><tr><td><strong>区域管理 → 区域列表</strong></td><td>编辑区域基本信息；关闭私信等与本功能间接相关的项</td></tr></tbody></table><p>平台默认行（region_id=0）作为兜底；各区域可单独覆盖。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li><strong>Token 测试</strong>：系统配置页点击「立即获取 Token」，两项均成功。</li><li><strong>小程序登录</strong>：在已开启登录的区域，用小程序尝试微信一键登录，能进入首页。</li><li><strong>支付</strong>：发起一笔小额测试订单，支付成功后 <strong>财务管理 → 资金交易</strong> 可见流水。</li><li><strong>回调</strong>：<strong>系统监控 → 系统状态</strong> 中支付相关状态正常，无持续验签失败告警。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Token 获取失败</strong></p><ul><li>检查 AppID / AppSecret 是否复制完整、无多余空格。</li><li>确认服务器能访问微信 API（防火墙 / 代理未拦截）。</li></ul><p><strong>用户无法微信登录</strong></p><ul><li>确认 <strong>区域管理 → 用户配置</strong> 中对应登录方式已开启。</li><li>小程序：确认小程序 AppID 与代码包一致；体验版需加入体验成员。</li></ul><p><strong>支付成功但订单未更新</strong></p><ul><li>核对商户平台回调 URL 是否与上文完全一致（含 <code>https</code>、路径大小写）。</li><li>确认 API 证书、平台公钥与商户平台一致；反向代理勿缓存 POST 请求。</li></ul><p><strong>H5 公众号登录跳转失败</strong></p><ul><li>公众号后台 <strong>网页授权域名</strong> 须与站点域名一致且已备案。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/payment">支付与提现</a></li><li><a href="/config/user-rules">用户规则</a></li><li><a href="/config/system-settings">系统配置总览</a></li></ul>',43)])])}const u=a(n,[["render",s]]);export{c as __pageData,u as default};
